          "fullDescription": "من أكثر أمراض المشاتل شيوعًا وخطورةً على مستوى العالم. يهاجم البادرات قبل الإنبات (Pre-emergence Damping-off) فيتعفن الجذير في التربة قبل الظهور، أو بعد الإنبات مباشرةً (Post-emergence Damping-off) فتتعفن السويقة عند سطح التربة وتسقط الشتلة. يمكن أن يُفني محصول مشتل بالكامل في 3-5 أيام. P. aphanidermatum الأكثر عدوانية في المناخات الحارة كمصر، بينما P. ultimum سائد في الأجواء الباردة.",
